const counter = (() => {
  let count = 0;

  return {
    add: () => {
      count = count + 1;
    },
    get: () => count,
  };
})();

function getCount() {
  counter.add();
  counter.add();

  return counter.get();
}

function runCart(prices) {
  const cart = (() => {
    const items = [];

    return {
      add: (price) => items.push(price),
      summary: () => {
        let total = 0;

        for (const price of items) {
          total += price;
        }

        return { count: items.length, total };
      },
    };
  })();

  for (const price of prices) {
    cart.add(price);
  }

  return cart.summary();
}
